#include <iostream>
using namespace std;

struct tnode {
    int val;
    tnode *left;
    tnode *right;
};

// cppquest: sends a picture of the tree to the visualizer after each step.
// It writes to cerr (not cout), so it never affects the graded output.
void snapshot(tnode *t, bool top = true) {
    if (top) cerr << "@@T ";
    if (t == nullptr) cerr << "# ";
    else { cerr << t->val << " "; snapshot(t->left, false); snapshot(t->right, false); }
    if (top) cerr << endl;
}


// void insert(tnode *&t, int v)
// t is null: t = new node holding v (children null)
// v < t->val: recurse into t->left, else into t->right
// Write it here:


int main() {
    tnode *root = nullptr;
    int v;
    snapshot(root);
    while (cin >> v && v != -1) {
        insert(root, v);
        snapshot(root);
    }
    if (root == nullptr) {
        cout << "empty\n";
        return 0;
    }
    cout << "root=" << root->val << "\n";
    if (root->left) cout << "left=" << root->left->val << "\n";
    else cout << "left=none\n";
    if (root->right) cout << "right=" << root->right->val << "\n";
    else cout << "right=none\n";
    return 0;
}

