// The base class. Everything a balanced tree will need is already here.
class grove {
protected:                  // the class itself AND classes built on it may use these; main may not
    tnode *root;
    int nCount;
    bool insertHelper(tnode *&t, kvpair p);
    int heightHelper(tnode *t) const;
public:
    grove() { root = nullptr; nCount = 0; }
    virtual bool insert(kvpair p) { return insertHelper(root, p); }   // virtual: a class built on grove may replace this
    int height() const { return heightHelper(root); }
    bool balanced() const {
        if (root == nullptr) return true;
        int d = heightHelper(root->left) - heightHelper(root->right);
        return d >= -1 && d <= 1;
    }
};

bool grove::insertHelper(tnode *&t, kvpair p) {
    bool r = false;
    if (t) {
        if (p.key < t->p.key)      r = insertHelper(t->left, p);
        else if (p.key > t->p.key) r = insertHelper(t->right, p);
    } else {
        t = new tnode;
        t->p = p;
        t->left = t->right = nullptr;
        nCount++;
        r = true;
    }
    return r;
}

int grove::heightHelper(tnode *t) const {
    if (t == nullptr) return 0;
    int hl = heightHelper(t->left), hr = heightHelper(t->right);
    return 1 + (hl > hr ? hl : hr);
}

