int main() {
    list *L = new list();                   // default: capacity 100, expandSize 5
    string cmd;

    // a tiny command interpreter: one command per line from the test input
    while (cin >> cmd) {
        if (cmd == "new") {
            unsigned int cap, exp;
            cin >> cap >> exp;
            delete L;
            L = new list(cap, exp);
            cout << "new list: capacity " << L->getCapacity() << " expand "
                 << L->getExpandSize() << " count " << L->getCount() << endl;
        }
        else if (cmd == "add") {
            KEY_VALUE kv;
            cin >> kv.key >> kv.value;
            cout << "add " << kv.key << (L->add(kv) ? " ok" : " FAILED") << endl;
        }
        else if (cmd == "print") {
            int limit;
            cin >> limit;
            L->printIt(limit);
        }
        else if (cmd == "count") {
            cout << "count " << L->getCount() << " capacity " << L->getCapacity() << endl;
        }
        else if (cmd == "expand") {
            cout << "expand" << (L->expand() ? " ok" : " FAILED") << endl;
        }
        else if (cmd == "setexpand") {
            unsigned int n;
            cin >> n;
            L->setExpandSize(n);
            cout << "expandSize now " << L->getExpandSize() << endl;
        }
        else if (cmd == "insert") {
            KEY_VALUE kv;
            cin >> kv.key >> kv.value;
            cout << "insert " << kv.key << (L->insert(kv) ? " ok" : " FAILED") << endl;
        }
        else if (cmd == "delfirst") {
            KEY_VALUE kv;
            if (L->deleteFirst(kv)) cout << "deleteFirst " << kv.key << " " << kv.value << endl;
            else cout << "deleteFirst: empty" << endl;
        }
        else if (cmd == "dellast") {
            KEY_VALUE kv;
            if (L->deleteLast(kv)) cout << "deleteLast " << kv.key << " " << kv.value << endl;
            else cout << "deleteLast: empty" << endl;
        }
        else if (cmd == "readat") {
            unsigned int i;
            KEY_VALUE kv;
            kv.key = -1; kv.value = -1;
            cin >> i;
            if (L->readAt(i, kv)) cout << "readAt " << i << ": " << kv.key << " " << kv.value << endl;
            else cout << "readAt " << i << ": invalid (kv still " << kv.key << ")" << endl;
        }
        else if (cmd == "index") {
            int key;
            cin >> key;
            unsigned int i = L->getIndex(key);
            if (i == NEG_RESULT) cout << "index of " << key << ": NEG_RESULT" << endl;
            else cout << "index of " << key << ": " << i << endl;
        }
        else if (cmd == "clear") {
            L->clear();
            cout << "cleared: count " << L->getCount() << " capacity " << L->getCapacity()
                 << " expand " << L->getExpandSize() << endl;
        }
        else if (cmd == "insertat") {
            unsigned int i;
            KEY_VALUE kv;
            cin >> i >> kv.key >> kv.value;
            cout << "insertAt " << i << " " << kv.key << (L->insertAt(i, kv) ? " ok" : " FAILED") << endl;
        }
        else if (cmd == "insertbykey") {
            KEY_VALUE kv;
            cin >> kv.key >> kv.value;
            cout << "insertByKey " << kv.key << (L->insertByKey(kv) ? " ok" : " FAILED") << endl;
        }
        else if (cmd == "delat") {
            unsigned int i;
            KEY_VALUE kv;
            cin >> i;
            if (L->deleteAt(i, kv)) cout << "deleteAt " << i << ": " << kv.key << " " << kv.value << endl;
            else cout << "deleteAt " << i << ": invalid" << endl;
        }
        else if (cmd == "copy") {
            list *L2 = new list(L);
            KEY_VALUE kv;
            kv.key = 999; kv.value = 999;
            L2->add(kv);                    // change the copy ...
            cout << "copy: count " << L2->getCount() << " original count " << L->getCount() << endl;
            L2->printIt(-1);
            delete L2;                      // ... and destroy it; the original must survive
            cout << "original after copy destroyed:" << endl;
            L->printIt(-1);
        }
        else if (cmd == "cat") {
            list other(2, 1);
            KEY_VALUE kv;
            kv.key = 500; kv.value = 5; other.add(kv);
            kv.key = 600; kv.value = 6; other.add(kv);
            list *joined = L->cat(&other);
            cout << "cat: count " << joined->getCount() << " capacity " << joined->getCapacity() << endl;
            joined->printIt(-1);
            delete joined;
        }
        else if (cmd == "catnull") {
            list *joined = L->cat(NULL);
            cout << "cat NULL: count " << joined->getCount() << " capacity " << joined->getCapacity() << endl;
            joined->printIt(-1);
            delete joined;
        }
        else if (cmd == "shorten") {
            string onoff;
            cin >> onoff;
            L->setShortenEnabled(onoff == "on");
            cout << "shorten " << (L->getShortenEnabled() ? "on" : "off") << endl;
        }
        else if (cmd == "printback") {
            int limit;
            cin >> limit;
            L->printItBackwards(limit);
        }
        else cout << "unknown command " << cmd << endl;
    }

    delete L;
    return 0;
}
